package EmployeeManagementSystem.service;
import EmployeeManagementSystem.entity.*; import EmployeeManagementSystem.repository.*; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class InternalMobilityServiceImpl implements InternalMobilityService{
 private final InternalJobPostingRepository posts; private final InternalJobApplicationRepository apps;
 public InternalMobilityServiceImpl(InternalJobPostingRepository p,InternalJobApplicationRepository a){posts=p;apps=a;}
 public List<InternalJobPosting> postings(boolean all){return all?posts.findAllByOrderByCreatedAtDesc():posts.findByStatusOrderByApplicationDeadlineAsc("OPEN");}
 public InternalJobPosting createPosting(InternalJobPosting x,String u,String n){if(x.getTitle()==null||x.getTitle().isBlank()||x.getDescription()==null||x.getDescription().isBlank())throw new IllegalArgumentException("Title and description are required.");x.setId(null);x.setPostingNumber("IJP-"+System.currentTimeMillis());x.setCreatedByUserId(u);x.setCreatedByName(n);x.setStatus("OPEN");return posts.save(x);}
 public InternalJobPosting updatePosting(Long id,InternalJobPosting x){InternalJobPosting p=posts.findById(id).orElseThrow(()->new NoSuchElementException("Job posting not found."));p.setTitle(x.getTitle());p.setDescription(x.getDescription());p.setDepartment(x.getDepartment());p.setLocation(x.getLocation());p.setEmploymentType(x.getEmploymentType());p.setRequiredSkills(x.getRequiredSkills());p.setApplicationDeadline(x.getApplicationDeadline());return posts.save(p);}
 public InternalJobPosting closePosting(Long id){InternalJobPosting p=posts.findById(id).orElseThrow(()->new NoSuchElementException("Job posting not found."));p.setStatus("CLOSED");return posts.save(p);}
 public List<InternalJobApplication> myApplications(String u){return apps.findByApplicantUserIdOrderByCreatedAtDesc(u);} public List<InternalJobApplication> applications(){return apps.findAllByOrderByCreatedAtDesc();}
 public InternalJobApplication apply(Long postingId,InternalJobApplication x,String u,String n){InternalJobPosting p=posts.findById(postingId).orElseThrow(()->new NoSuchElementException("Job posting not found."));if(!"OPEN".equals(p.getStatus()))throw new IllegalArgumentException("This job posting is closed.");if(p.getApplicationDeadline()!=null&&p.getApplicationDeadline().isBefore(LocalDate.now()))throw new IllegalArgumentException("Application deadline has passed.");if(apps.existsByPostingIdAndApplicantUserId(postingId,u))throw new IllegalArgumentException("You have already applied for this position.");x.setId(null);x.setPosting(p);x.setApplicantUserId(u);x.setApplicantName(n);x.setStatus("SUBMITTED");return apps.save(x);}
 public InternalJobApplication review(Long id,String s,String c,String r){InternalJobApplication a=apps.findById(id).orElseThrow(()->new NoSuchElementException("Application not found."));if(!Set.of("UNDER_REVIEW","SHORTLISTED","INTERVIEW","SELECTED","REJECTED","WITHDRAWN").contains(s))throw new IllegalArgumentException("Invalid application status.");a.setStatus(s);a.setReviewerUserId(r);a.setReviewerComment(c);a.setReviewedAt(LocalDateTime.now());return apps.save(a);}
}
